commands.command:
/bin/zsh -lc "node --experimental-transform-types --disable-warning=ExperimentalWarning --disable-warning=MODULE_TYPELESS_PACKAGE_JSON --input-type=module - <<'JS'
import {readDashboard} from './src/dashboard.ts';
import {readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
const {projects:[p]}=await readDashboard([{key:'www',name:'WWW',path:process.cwd(),kind:'www'}]);
const groups={};
const rows=p.cards.filter(c=>c.status==='verifying');
for(const c of rows){
 const w=JSON.parse(await readFile(resolve(c.sourcePath),'utf8'));
 const next=w.workflow?.nextAction ?? (c.sourcePath.startsWith('docs/work/Native/')?'nativeSummary':'unknown');
 (groups[next]??=[]).push({path:c.sourcePath.split('/').slice(-3,-1).join('/'),blocked:c.blockedReason});
}
console.log(JSON.stringify({coverage:p.coverage,reviewColumn:rows.length,groups:Object.fromEntries(Object.entries(groups).map(([k,v])=>[k,{count:v.length,items:k==='review'||k==='unknown'?v:undefined}]))},null,2));
JS"
